#include <bits/stdc++.h>
using namespace std;
// gen_random n updates seed mode alphabet
// Modes: 0=random, 1=constant, 2=periodic, 3=mirrored, 4=Fibonacci.
int main(int argc,char**argv){int n=argc>1?stoi(argv[1]):1000,u=argc>2?stoi(argv[2]):500;unsigned long long seed=argc>3?stoull(argv[3]):1;int mode=argc>4?stoi(argv[4]):0,A=argc>5?stoi(argv[5]):1000000001;if(n<1||u<0||A<1||A>1000000001||mode<0||mode>4)return 2;mt19937_64 g(seed);auto rnd=[&](unsigned long long bound){return g()%bound;};auto symbol=[&](){return(int)rnd(A);};vector<int>s(n);int a=symbol(),b=symbol();if(A>1)while(b==a)b=symbol();vector<int>fib{a},prev{b};while((int)fib.size()<n){vector<int>x=fib;x.insert(x.end(),prev.begin(),prev.end());prev.swap(fib);fib.swap(x);}for(int i=0;i<n;++i)s[i]=mode==1?a:mode==2?(i%3?a:b):mode==4?fib[i]:symbol();if(mode==3)for(int i=0;i<n/2;++i)s[n-1-i]=s[i];cout<<n<<' '<<2*u+1<<'\n';for(int i=0;i<n;++i)cout<<s[i]<<(i+1==n?'\n':' ');cout<<"4\n";for(int step=0;step<u;++step){int l=1+rnd(n),r=l+rnd(n-l+1);int edge=step%17;if(edge==0)l=1,r=n;else if(edge==1)r=l;else if(edge==2)l=1;else if(edge==3)r=n;int type=1+rnd(3);if(type==1){int val=mode==1?a:mode==2||mode==4?(rnd(2)?a:b):symbol();if(step%19==0)val=1000000000;if(step%23==0)val=0;cout<<"1 "<<l<<' '<<val<<'\n';}else if(type==2)cout<<"2 "<<l<<' '<<r<<'\n';else{unsigned long long k=rnd(1000000000000000001ULL);if(step%7==0)k=0;else if(step%7==1)k=r-l+1;cout<<"3 "<<l<<' '<<r<<' '<<k<<'\n';}cout<<"4\n";}}
